from fastmcp.server import FastMCP


# Create a sub-server with math tools
math_server = FastMCP(name="math_server", instructions="Provides mathematical operations")


@math_server.tool(description="Add two numbers")
def add(a: float, b: float) -> float:
    """Add two numbers together."""
    return a + b


@math_server.tool(description="Subtract two numbers")
def subtract(a: float, b: float) -> float:
    """Subtract b from a."""
    return a - b


@math_server.tool(description="Multiply two numbers")
def multiply(a: float, b: float) -> float:
    """Multiply two numbers together."""
    return a * b


@math_server.tool(description="Divide two numbers")
def divide(a: float, b: float) -> float:
    """Divide a by b."""
    if b == 0:
        raise ValueError("Division by zero")
    return a / b


# Create the main server and mount the math server under the "math" prefix
main_server = FastMCP(name="main_server", instructions="Main server with math tools")


@main_server.tool(description="Say hello")
def greet(name: str) -> str:
    """Greet someone by name."""
    return f"Hello, {name}!"


# Mount the math server under the "math" namespace
main_server.mount(math_server, namespace="math")


# Run the main server (tools from math_server are now accessible as math_add, math_subtract, etc.)
if __name__ == "__main__":
    main_server.run()

